struct Base { using Type = int; };

template<typename T>
struct DependentContext {
    // Phase 1: Non-dependent name lookup
    Base::Type x; // Base is known; resolution happens now.

    // Phase 2: Dependent name lookup (deferred)
    // 'typename' needed to tell compiler T::Type is a type,
    // not a static member variable/value.
    typename T::Type y;

    void call_dep_member() {
        T::some_func(); // Dependent non-template call

        // Requires 'template' keyword if calling a dependent member template
        this->template dep_member_template<int>();
    }
};
